from __future__ import annotations
from math import sqrt


def equal_pair_probability(amplitude: float) -> tuple[float, float]:
    """Return Born probabilities for two distinct labels with equal amplitude."""
    if amplitude == 0.0:
        raise ValueError("the state must be nonzero")
    norm_sq = 2.0 * amplitude * amplitude
    weight = amplitude * amplitude / norm_sq
    return weight, weight


if __name__ == "__main__":
    for a in (1 / sqrt(2), 1e-6, 1e-100):
        print(f"a={a:.3e}: P(0), P(epsilon) = {equal_pair_probability(a)}")

from __future__ import annotations


def suppressed_branch(delta: float) -> tuple[float, float]:
    """Normalize squared amplitudes 1 and delta squared."""
    if delta < 0.0:
        raise ValueError("delta must be nonnegative")
    denominator = 1.0 + delta * delta
    return 1.0 / denominator, delta * delta / denominator


if __name__ == "__main__":
    for exponent in range(1, 9):
        delta = 10.0 ** (-exponent)
        ordinary, small = suppressed_branch(delta)
        print(f"delta={delta:.0e}  ordinary={ordinary:.12f}  small={small:.3e}")

from __future__ import annotations
from dataclasses import dataclass


@dataclass(frozen=True)
class LexWeight:
    ordinary: float
    infinitesimal_units: int

    def __add__(self, other: "LexWeight") -> "LexWeight":
        return LexWeight(self.ordinary + other.ordinary,
                         self.infinitesimal_units + other.infinitesimal_units)

    def standard_part(self) -> float:
        return self.ordinary


if __name__ == "__main__":
    atoms = [LexWeight(0.0, 1) for _ in range(5)]
    total = LexWeight(1.0, len(atoms))
    print("standard total:", total.standard_part())
    print("standard atom masses:", [atom.standard_part() for atom in atoms])

